   Maintenance: "Утримання",
   MaintenanceAndMorale: "Утримання та бойовий дух",
   MaintenanceIsDeterminedPrimarilyByTheTilesUnrestLevel: "Утримання залежить насамперед від рівня заворушень у володінні.",
   MakeAnExampleOfTheGuilty: "Покарати винних прилюдно, іншим на пересторогу",
   MakeCore: "Зробити корінним",
   MakeCoreCost: "Вартість перетворення на корінне",
   MakeDurocortorumOurCoreDesc:
      "Щойно анексоване володіння ще не стало корінним — некорінні володіння сплачують менше податків і мають вищу вартість управління. Коли вартість управління перевищує управлінську спроможність, настає надмірне розширення, яке шкодить нашій провінції. Щоб інтегрувати володіння й зробити його корінним, треба витратити <icon>Administrative</icon>адміністративні очки — дотримуйтеся вказівок на екрані.",
   MakeGovernorGeneral: "Зробити намісника полководцем",
   MakeWarSpeech: "Виголосити воєнну промову",
   MakingGovernorGeneralDoesNotCostGold$1$2$3$4: "Призначення намісника полководцем не коштує золота, але додасть <i>$1 до шансу смерті</i>. Базова майстерність намісника-полководця: $2/$3/$4.",
   Manpower: "Людські ресурси",
   ManpowerFormsTheBasePoolFromWhichOurStandingArmyIsConscripted: "Людські ресурси — це основний резерв, з якого набирають наше постійне військо.",
   MarriageAlliance: "Шлюбний союз",
   MartinOfToursAndTheCloak: "Мартин Турський і плащ",
   MartinOfToursAndTheCloakDesc: "Слава Мартина, колишнього воїна, що став аскетом, шириться Галлією. Його вчинок — він розрізав свій плащ, щоб зодягнути жебрака, — пробуджує побожність серед бідних і тривогу серед традиційної знаті, що боїться зростання впливу святих мужів.",
   MartinShallBeVeneratedButThatsAll: "Мартина шануватимуть, але не більше",
   MartinShallLeadOurPeopleToVirtue: "Мартин поведе наш народ до чесноти",
   Max: "Макс.",
   MerchantsAccusedOfMalfeasance: "Купців звинувачено в зловживаннях",
   MerchantsAccusedOfMalfeasanceDesc: "Чутки про корупцію множаться: наші урядовці знайшли докази того, що деякі купці давно ухилялися від податків, збагачуючись коштом провінції.",
