   Missions: "Місії",
   ModifierDefenseDesc: "Оборона збільшує воєнний рахунок, потрібний для захоплення цього володіння, коли воно є метою війни.",
   ModifierDiplomatDesc: "Щоб підписувати договори з провінцією, покращувати з нею відносини або проникати в неї, туди спершу треба направити дипломата.",
   ModifierDiplomaticRangeDesc: "Дипломатичні дії можна здійснювати лише щодо провінцій, дипломатична відстань до яких не перевищує нашої дипломатичної досяжності. Дипломатична відстань — це найкоротша відстань від нашої провінції до їхньої столиці.",
   ModifierGoverningCapacityDesc: "Управлінська спроможність — це найбільша загальна вартість управління, яку наша провінція може витримати без надмірного розширення.",
   ModifierInfrastructureUpgradeCostDesc: "Вартість покращення інфраструктури — це ціна покращення інфраструктури володіння. Кожен наступний рівень коштує дорожче.",
   ModifierImproveRelationsRateDesc: "Щомісячний приріст ставлення під час покращення відносин із провінцією",
   ModifierInfiltrationRateDesc: "Щомісячний приріст проникнення під час проникнення в провінцію",
   ModifierWarScoreDesc: "Воєнний рахунок, потрібний для перемоги у війні, залежить від оборони володінь, що є метою війни.",
   ModifierMakeCoreCostDesc: "Вартість перетворення на корінне — це ціна перетворення володіння на корінне. Кожне таке перетворення підвищує ціну наступного.",
   ModifierMonthlyInterestRateDesc: "На наші непогашені позики щомісяця нараховуються відсотки за цією ставкою.",
   ModifierPopulationUpgradeCostDesc: "Вартість покращення населення — це ціна покращення населення володіння. Кожен наступний рівень коштує дорожче.",
   ModifierPrestigeDesc: "Престиж показує, як нашу провінцію сприймають інші провінції. Він потрібен для різних дипломатичних дій.",
   ModifierProductionUpgradeCostDesc: "Вартість покращення виробництва — це ціна покращення виробництва володіння. Кожен наступний рівень коштує дорожче.",
   ModifierResearchCostDesc: "Вартість дослідження — це ціна дослідження технології. Кожна досліджена технологія підвищує ціну наступної.",
