   Rebirth: "Відродження",
   RebirthAndStartANewRun: "Відродитися й почати нове проходження",
   RebirthAndStartANewRunDesc:
      "Restitutor — це <i>інкрементальна</i> глобальна стратегія: кожне проходження дає постійні бонуси, завдяки яким наступне просувається швидше й сягає далі. Ця система називається <i>відродженням</i>.<br>Під час відродження володіння, які ми <i>анексували й зробили корінними</i>, перетворюються на <icon>Legacy</icon>очки спадщини — вони переходять у майбутні проходження й дають потужні бонуси.<br>Для наступного проходження можна обрати іншу провінцію — дотримуйтеся вказівок на екрані, щоб відродитися.<br>Після відродження навчання завершиться. Зі здобутими знаннями ми готові творити власну стратегію та торувати власний шлях — відтепер хід історії вирішуємо ми.",
   ReceivedAGiftFrom$1: "Отримано дар від провінції $1",
   Reconquista: "Реконкіста",
   Reconquista$1: "Реконкіста ($1)",
   RecruitAGeneral: "Найняти полководця",
   RecruitAGeneralDescV2:
      "Полководець збільшить бойову міць нашої армії. Можна найняти полководця, що збільшить витрати на утримання армії, або зробити полководцем намісника, що підвищить шанс його смерті. Дотримуйтеся вказівок на екрані, щоб найняти полководця.<br>Після кожної виграної війни полководець отримує очки майстерності, які можна витратити на подальше зміцнення бойової міці. 50% здобутих очок майстерності переходять далі, а всі вдосконалення майстерності скидаються.",
   RecruitAGeneralTutorial: "Найняти полководця",
   RecruitingAGeneralCostsGoldEveryMonthAGeneralHasABaseSkillOf$1: "Найманий полководець коштує золота <i>щомісяця</i>. Базова майстерність полководця — $1.",
