   TimedActionAppeaseDesc$1: "Задобрення бунтівників зменшує <i>заколот</i> на $1. Доступне лише тоді, коли у володінні зараз <i>немає</i> заколоту.",
   TimedActionCrackdownDesc$1$2$3: "Придушення бунтівників скидає <i>заколот</i> до $1, але збільшує <i>заворушення</i> на $2 на $3 р. Доступне лише тоді, коли володіння охоплене заколотом.",
   TimedActionDemandElectionBackingDesc$1: "Вимога виборчої підтримки змушує їх підтримати нас на найближчих виборах консулів, збільшуючи нашу провінційну підтримку на $1.",
   TimedActionDemandTileDesc: "Якщо нашу вимогу як великої держави приймуть, вони мусять поступитися нам володінням.",
   TimedActionDemandTributeDesc: "Якщо нашу вимогу данини як великої держави приймуть, ми одноразово отримаємо золото.",
   TimedActionDenounceDesc$1$2$3: "Засудження провінції погіршує її ставлення до нас на $1 і збільшує наш престиж на $2 ($3, якщо це наш суперник).",
   TimedActionDeterAggressionDesc$1$2: "Стримування агресії зобов'язує нас виступити на боці оборонця, якщо ця провінція нападе на іншу. Доки стримування діє, наш престиж збільшено на $1 ($2, якщо це наш суперник).",
   TimedActionDissolveTreatyDesc: "Розірвання договору припиняє дипломатичний договір провінції з іншою провінцією. Крім того, провінція не зможе укладати нових договорів.",
   TimedActionEvangelizeTileDesc: "Проповідь віри в нехристиянському володінні навертає його до релігії нашої провінції.",
   TimedActionFabricateCasusBelliDesc: "Фабрикування casus belli дає нам проти них casus belli <i>Дипломатична суперечка</i>.",
   TimedActionForceAttackDesc$1$2: "Під час потужного удару, якщо наш напад відіб'ють, ми втрачаємо $1 постійного війська замість $2 воєнного рахунку.",
   TimedActionFortifyBordersDesc$1: "Укріплення кордонів збільшує людські ресурси наших володінь, що межують із володіннями — метою війни, на $1.",
   TimedActionGuaranteeDefenseDesc$1: "Гарантія захисту зобов'язує нас вступити в їхню оборонну війну, якщо на них нападуть. Доки гарантія діє, їхнє ставлення до нас покращено на $1.",
   TimedActionHireMercenariesDesc: "Найм найманців негайно поповнює наше військо до цільового набору.",
   TimedActionInciteUnrestDesc$1: "Підбурювання заворушень на кордоні збільшує заворушення в їхніх володіннях, що межують із нашою провінцією, на $1.",
   TimedActionPlunderWarTileDesc: "Пограбування володіння, охопленого війною, зменшує <i>потрібний воєнний рахунок</i> і погіршує покращення володіння.",
   TimedActionPublicEnemyDesc$1: "Оголошення провінції <i>ворогом держави</i> зменшує її <i>престиж</i> і <i>бойову міць</i> на $1. Усі інші провінції отримують проти неї casus belli <i>Ворог держави</i>.",
   TimedActionRequestMilitaryAidDesc$1$2: "Прохання про військову допомогу збільшує нашу бойову міць на $1 і зменшує бойову міць нашого клієнта на $2.",
   TimedActionRevealElectionBackingDesc: "Викриття виборчої підтримки дає змогу дізнатися, яких двох кандидатів вони підтримують.",
   TimedActionSetGovernmentFocusDesc: "Пріоритет уряду збільшує щомісячне надходження обраного напряму коштом двох інших.",
   TimedActionSubvertGarrisonDesc$1: "Підкуп прикордонної залоги зменшує оборону їхніх володінь, що межують із нашою провінцією, на $1.",
   TimedActionSummonGovernorDesc$1$2: "Виклик намісника клієнта збільшує наш престиж на $1 і зменшує престиж клієнта на $2.",
   TimedActionUpgradeInfrastructureDesc: "Покращення інфраструктури володіння коштує адміністративних очок і збільшує його <i>земельний податок</i>.",
   TimedActionUpgradePopulationDesc: "Покращення населення володіння коштує військових очок і збільшує його <i>людські ресурси</i>.",
   TimedActionUpgradeProductionDesc: "Покращення виробництва володіння коштує дипломатичних очок і збільшує його <i>виробіток</i>.",
