   UnpauseTheGame: "Зняти гру з паузи",
   UnpauseTheGameDesc:
      "Restitutor — класична глобальна стратегія в стилі <q>реальний час із паузою</q>, і після завантаження гра стоїть на паузі. Коли будемо готові, зніміть гру з паузи, натиснувши кнопку паузи (підсвічено) або клавішу <i>пробіл</i>.<br>Типова швидкість гри: 1 секунда (реального часу) = 1 день (ігрового часу). Швидкість можна змінити на панелі вгорі праворуч.",
