   InfantryCountersCavalryAndIsCounteredByRangedUnits: "Піхота ефективна проти <i>кінноти</i>, але вразлива до <i>стрільців</i>.",
   InfantryEffectivenessIncreaseDesc$1$2: "Кожні $1 ворожої бойової міці, що припадають на кінноту, <i>підвищують</i> ефективність нашої піхоти на $2.",
