   RangedEffectivenessIncreaseDesc$1$2: "Кожні $1 ворожої бойової міці, що припадають на піхоту, <i>підвищують</i> ефективність наших стрільців на $2.",
   RangedEffectivenessDecreaseDesc$1$2: "Кожні $1 ворожої бойової міці, що припадають на кінноту, <i>знижують</i> ефективність наших стрільців на $2.",
   CavalryCountersRangedUnitsAndIsCounteredByInfantry: "Кіннота ефективна проти <i>стрільців</i>, але вразлива до <i>піхоти</i>.",
   CavalryEffectivenessIncreaseDesc$1$2: "Кожні $1 ворожої бойової міці, що припадають на стрільців, <i>підвищують</i> ефективність нашої кінноти на $2.",
   CavalryEffectivenessDecreaseDesc$1$2: "Кожні $1 ворожої бойової міці, що припадають на піхоту, <i>знижують</i> ефективність нашої кінноти на $2.",
   CavalryPredominanceDesc$1$2$3: "$1 до бойової міці за кожні $2 частки кінноти у складі армії (до $3)",
   RangedPredominanceDesc$1$2$3: "$1 до бойової міці за кожні $2 частки стрільців у складі армії (до $3)",
   ExecuteABattlePlan: "Виконати бойовий план",
   TimedActionExecuteBattlePlanDesc$1: "Витратити $1 очк. майстерності полководця, щоб отримати воєнний рахунок, що дорівнює сумі рівнів майстерності полководця в командуванні піхотою, стрільцями й кіннотою.",
   MakeWarSpeechDesc$1$2: "Воєнна промова дає нам $1 потрібного воєнного рахунку (з округленням донизу, щонайменше $2) і можлива лише протягом першого року війни.",
   DecimateOurArmyDesc$1$2$3: "Децимація скорочує наше постійне військо на $1 і дає нам $2 потрібного воєнного рахунку (з округленням донизу, щонайменше $3).",
