   AutonomyHasChanged: "Автономію змінено",
   From$1To$2: "З $1 до $2",
   AdjustAutonomy: "Змінити автономію",
   TimedActionAdjustAutonomyDesc$1$2$3$4: "Кожні $1 автономії зменшують земельний податок, виробіток і людські ресурси на $2; заворушення — на $3; вартість управління, оборону й утримання володіння — на $4. Усі зміни автономії в провінції мають спільний час очікування.",
   AutomaticallySettlePositiveUnrestDesc: "Щомісяця, коли ця дія доступна, заворушення вгамовуються у володінні з найбільшими додатними заворушеннями, автономію якого можна змінити. Якщо жодне володіння не підходить, нічого не відбувається.",
